INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('product-media', 'product-media', TRUE, 5242880, ARRAY['image/jpeg', 'image/png', 'image/webp']) ON CONFLICT (id) DO UPDATE SET public = EXCLUDED.public, file_size_limit = EXCLUDED.file_size_limit, allowed_mime_types = EXCLUDED.allowed_mime_types;
CREATE POLICY product_media_public_read ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'product-media');
CREATE POLICY product_media_admin_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'product-media' AND lower(auth.jwt() ->> 'email') = 'atenasmodafitness@gmail.com');
CREATE POLICY product_media_admin_update ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'product-media' AND lower(auth.jwt() ->> 'email') = 'atenasmodafitness@gmail.com') WITH CHECK (bucket_id = 'product-media' AND lower(auth.jwt() ->> 'email') = 'atenasmodafitness@gmail.com');
CREATE POLICY product_media_admin_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'product-media' AND lower(auth.jwt() ->> 'email') = 'atenasmodafitness@gmail.com');